//! The product file-icon themes (`packages/shared-ui/src/file`): which glyph
//! a file shows. Which kind a file is comes from the format registry
//! (`crate::formats`). Pure: no GPUI. The glyphs are generated by
//! `tools/import-file-icons.mjs`.
use crate::formats;
use serde::Deserialize;
use std::{collections::HashMap, sync::OnceLock};

#[derive(Deserialize)]
struct Glyph {
    light: String,
    dark: String,
}
#[derive(Deserialize)]
struct Catalog {
    order: Vec<String>,
    themes: HashMap<String, HashMap<String, Glyph>>,
}
fn catalog() -> &'static Catalog {
    static DATA: OnceLock<Catalog> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(include_str!("../assets/file-icons.json")).expect("generated icons")
    })
}

/// Product icon themes in Settings order (`FILE_ICON_THEME_ORDER`).
pub fn themes() -> impl Iterator<Item = &'static str> {
    catalog().order.iter().map(String::as_str)
}
pub fn is_theme(id: &str) -> bool {
    themes().any(|t| t == id)
}

/// `getFileSemanticKind(name)` for files; folders are always `folder`.
pub fn kind(path: &str, folder: bool) -> &'static str {
    if folder {
        return "folder";
    }
    let format = formats::of(path);
    if format.is_known() {
        format.semantic_kind()
    } else {
        "file"
    }
}
/// Extension label drawn by label-style glyphs (`getLabel` fallback branch).
pub fn label(name: &str) -> String {
    formats::matched_extension(name)
        .map(|e| e.to_uppercase().chars().take(4).collect::<String>())
        .filter(|e| !e.is_empty())
        .unwrap_or_else(|| "FILE".into())
}
/// Asset path for a glyph; the asset source resolves it with `glyph_svg`.
pub fn asset_path(theme: &str, name: &str, folder: bool, dark: bool) -> String {
    let theme = if is_theme(theme) { theme } else { "default" };
    let kind = kind(name, folder);
    let mode = if dark { "dark" } else { "light" };
    let svg = &catalog().themes[theme][kind];
    if (if dark { &svg.dark } else { &svg.light }).contains("QQQQ") {
        format!("file-icons/{theme}/{kind}/{mode}/{}", label(name))
    } else {
        format!("file-icons/{theme}/{kind}/{mode}")
    }
}
/// Resolve `file-icons/<theme>/<kind>/<mode>[/<label>]` to SVG bytes.
pub fn glyph_svg(path: &str) -> Option<Vec<u8>> {
    let mut parts = path.strip_prefix("file-icons/")?.splitn(4, '/');
    let (theme, kind, mode) = (parts.next()?, parts.next()?, parts.next()?);
    let glyph = catalog().themes.get(theme)?.get(kind)?;
    let svg = if mode == "dark" {
        &glyph.dark
    } else {
        &glyph.light
    };
    let label = parts.next().unwrap_or("FILE");
    let escaped = label
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;");
    Some(svg.replace("QQQQ", &escaped).into_bytes())
}

/// `getExplorerDisplayName`: the Explorer hides a matched extension unless a
/// sibling shares the same primary name.
pub fn display_name(name: &str, folder: bool) -> (String, Option<String>) {
    if folder {
        return (name.into(), None);
    }
    match formats::matched_extension(name) {
        Some(ext) if name.len() > ext.len() + 1 => {
            let primary = &name[..name.len() - ext.len() - 1];
            if primary.is_empty() {
                (name.into(), None)
            } else {
                (primary.into(), Some(ext))
            }
        }
        _ => (name.into(), None),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn classification_and_display_follow_the_product_registry() {
        assert_eq!(kind("README.md", false), "markdown");
        assert_eq!(kind("src/main.rs", false), "code");
        assert_eq!(kind("data.json", false), "json");
        assert_eq!(kind("docs", true), "folder");
        assert_eq!(kind("unknown.qqq", false), "file");
        assert_eq!(
            display_name("README.md", false),
            ("README".into(), Some("md".into()))
        );
        assert_eq!(
            display_name(".gitignore", false),
            (".gitignore".into(), None)
        );
        assert_eq!(display_name("Makefile", false), ("Makefile".into(), None));
        assert_eq!(
            themes().collect::<Vec<_>>(),
            ["default", "lines", "semantic", "material", "minimal"]
        );
        let path = asset_path("semantic", "notes.txt", false, true);
        let svg = String::from_utf8(glyph_svg(&path).unwrap()).unwrap();
        assert!(svg.contains("TXT") && !svg.contains("QQQQ") && !svg.contains("var("));
        assert!(glyph_svg(&asset_path("default", "docs", true, false)).is_some());
    }
}
